SELECT MATERIAL_NAME
FROM T_MATERIAL_SCHEDULE_RESULT
WHERE DEL_FLAG = '0'
AND mix_area = #{mixArea}
AND schedule_date < #{scheduleDate}
AND schedule_date >= #{scheduleDate} - #{commonlyUsedDay}
AND MATERIAL_NAME in #{areaMaterial.materialName}
GROUP BY MATERIAL_NAME
having count(distinct schedule_date) = #{commonlyUsedDay}

SELECT ,
       (select RECIPE_TYPE_NAME from T_RECIPE_TYPE e where r.RECIPE_TYPE = e.RECIPE_TYPE_CODE AND e.DEL_FLAG='0') as RECIPE_TYPE_NAME,
       tlf.mid_finish_qty,tlf.night_finish_qty,tlf.day_finish_qty
FROM T_MATERIAL_SCHEDULE_RESULT r
left join t_lhfl_finish tlf on r.order_no = tlf.order_no and tlf.del_flag = 0
WHERE r.DEL_FLAG = '0'
AND r.SCHEDULE_DATE = #{schedule.scheduleDate}
AND r.mix_area = #{schedule.mixArea}

    AND r.machine_code in #{machine}


    AND r.PUBLISH_SUCCESS_COUNT > 0

