SELECT max(batch_no) batch_no
FROM T_MATERIAL_SCHEDULE_RESULT t
WHERE DEL_FLAG = '0'
AND SCHEDULE_DATE = #{scheduleDate}
AND MIX_AREA = #{mixArea}

SELECT max(CLASS_SHIFT) AS CLASS_SHIFT, max(CAPACITY) AS CAPACITY
  FROM T_MATERIAL_SCHEDULE_RESULT
 WHERE DEL_FLAG = '0'
 AND mix_area = #{mixArea}
 AND schedule_date = #{scheduleDate}
 AND machine_code = #{machineCode}
